<?php
require_once __DIR__ . '/../includes/portal_layout.php'; require_any_role(['admin','secretaria','direcao','coordenador']);
$user=current_user(); $role=user_has_role('admin')?'admin':(user_has_role('secretaria')?'secretaria':portal_user_role($user)); $id=(int)($_GET['id']??0); if($id<=0) redirect(APP_URL.'/pages/candidaturas.php');
$app=portal_one($pdo,"SELECT applications.*, courses.code AS course_code, courses.name AS course_name, courses.level AS course_level, courses.duration_years, academic_years.name AS academic_year FROM applications LEFT JOIN courses ON courses.id=applications.course_id LEFT JOIN academic_years ON academic_years.id=applications.academic_year_id WHERE applications.id=? LIMIT 1",[$id]); if(!$app){ $_SESSION['flash_error']='Candidatura não encontrada.'; redirect(APP_URL.'/pages/candidaturas.php'); }
$docs=portal_rows($pdo,"SELECT * FROM application_documents WHERE application_id=? ORDER BY id ASC",[$id]);
$history=portal_rows($pdo,"SELECT application_status_history.*, users.full_name AS actor_name FROM application_status_history LEFT JOIN users ON users.id=application_status_history.user_id WHERE application_id=? ORDER BY created_at DESC",[$id]); [$success,$error]=portal_flash();
$status=$app['status']??'pending'; $canOperate=(user_has_role('admin') || user_has_role('secretaria')); $canSecretary=$canOperate && in_array($status,['pending','in_review','missing_documents'],true); $canReject=$canOperate && !in_array($status,['rejected','credentials_sent'],true); $canGenerate=$canOperate && $status==='documents_validated';
portal_layout_start('candidaturas','Detalhes da Candidatura','Análise documental, decisão da secretaria e geração de credenciais.',$role);
?>
<?php if($success): ?><div class="ui-alert ui-alert-success"><?= e($success); ?></div><?php endif; ?><?php if($error): ?><div class="ui-alert ui-alert-error"><?= e($error); ?></div><?php endif; ?>
<div class="ui-panel"><div class="ui-panel-body"><div style="display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap"><div class="ui-person"><div class="ui-person-avatar" style="width:64px;height:64px;font-size:22px"><?= e(portal_initials_safe($app['full_name']??'')); ?></div><div><h1 style="margin:0"><?= e($app['full_name']); ?></h1><p style="color:var(--ui-muted)"><?= e($app['application_code']); ?><br><?= e($app['personal_email']); ?></p></div></div><span class="ui-badge <?= e(portal_badge_class($status)); ?>"><?= e(portal_label_status($status)); ?></span></div></div></div>
<div class="ui-split"><div><div class="ui-panel"><div class="ui-panel-header"><div><h2>Dados do candidato</h2><p>Informação pessoal e académica submetida.</p></div></div><div class="ui-panel-body"><table class="ui-table"><tbody><?php foreach(['full_name'=>'Nome completo','birth_date'=>'Data de nascimento','document_type'=>'Tipo de documento','document_number'=>'N.º documento','personal_email'=>'Email pessoal','phone'=>'Telefone','course_name'=>'Curso','course_level'=>'Nível','academic_year'=>'Ano letivo','created_at'=>'Data de submissão','rejection_reason'=>'Mensagem/observação'] as $k=>$label): ?><tr><th><?= e($label); ?></th><td><?= e(in_array($k,['created_at','birth_date'],true)?($k==='birth_date'?portal_short_date($app[$k]??null):portal_date($app[$k]??null)):($app[$k]??'-')); ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="ui-panel"><div class="ui-panel-header"><div><h2>Documentos enviados</h2><p><?= count($docs); ?> documento(s).</p></div></div><div class="ui-panel-body"><div class="ui-card-list"><?php if(empty($docs)): ?><div class="ui-empty">Nenhum documento enviado.</div><?php endif; ?><?php foreach($docs as $d): ?><div class="ui-card-row"><strong><?= e($d['document_name']??'Documento'); ?></strong><span style="color:var(--ui-muted)">Estado: <?= e(portal_label_status($d['status']??'')); ?></span><?php if(!empty($d['file_path'])): ?><a class="ui-btn ui-btn-ghost" target="_blank" href="<?= e(APP_URL.'/'.ltrim($d['file_path'],'/')); ?>">Abrir documento</a><?php endif; ?></div><?php endforeach; ?></div></div></div><div class="ui-panel"><div class="ui-panel-header"><div><h2>Histórico da candidatura</h2><p>Decisões e alterações de estado.</p></div></div><div class="ui-panel-body"><div class="ui-card-list"><?php if(empty($history)): ?><div class="ui-empty">Ainda não existe histórico.</div><?php endif; ?><?php foreach($history as $h): ?><div class="ui-card-row"><strong><?= e($h['action']??'Atualização'); ?></strong><span style="color:var(--ui-muted)"><?= e(portal_label_status($h['old_status']??'')); ?> → <?= e(portal_label_status($h['new_status']??'')); ?> · <?= e(portal_date($h['created_at']??null)); ?></span><p><?= nl2br(e($h['message']??'')); ?></p><small>Por: <?= e($h['actor_name']??'Sistema'); ?></small></div><?php endforeach; ?></div></div></div></div><aside><div class="ui-panel"><div class="ui-panel-header"><div><h2>Ações</h2><p>Fluxo da secretaria e administração.</p></div></div><div class="ui-panel-body" style="display:grid;gap:16px"><?php if($canSecretary): ?><form action="<?= e(APP_URL); ?>/actions/colocar_candidatura_em_analise.php" method="POST"><input type="hidden" name="application_id" value="<?= (int)$app['id']; ?>"><button class="ui-btn ui-btn-ghost" style="width:100%">Colocar em análise</button></form><form action="<?= e(APP_URL); ?>/actions/solicitar_documento.php" method="POST"><input type="hidden" name="application_id" value="<?= (int)$app['id']; ?>"><textarea class="ui-control" name="reason" placeholder="Explique o que falta ou precisa correção..."></textarea><button class="ui-btn ui-btn-ghost" style="width:100%;margin-top:10px">Solicitar documentos</button></form><form action="<?= e(APP_URL); ?>/actions/validar_documentos_candidatura.php" method="POST"><input type="hidden" name="application_id" value="<?= (int)$app['id']; ?>"><textarea class="ui-control" name="message" placeholder="Documentos analisados e validados pela secretaria."></textarea><button class="ui-btn ui-btn-primary" style="width:100%;margin-top:10px">Validar documentos</button></form><?php endif; ?><?php if($canReject): ?><form action="<?= e(APP_URL); ?>/actions/rejeitar_candidatura.php" method="POST"><input type="hidden" name="application_id" value="<?= (int)$app['id']; ?>"><textarea class="ui-control" name="reason" placeholder="Motivo da rejeição..." required></textarea><button class="ui-btn ui-btn-danger" style="width:100%;margin-top:10px">Rejeitar candidatura</button></form><?php endif; ?><?php if($canGenerate): ?><form action="<?= e(APP_URL); ?>/actions/aprovar_candidatura.php" method="POST"><input type="hidden" name="application_id" value="<?= (int)$app['id']; ?>"><button class="ui-btn ui-btn-secondary" style="width:100%">Gerar credenciais</button></form><?php endif; ?><a class="ui-btn ui-btn-ghost" href="<?= e(APP_URL); ?>/estado-candidatura.php?q=<?= urlencode($app['application_code']); ?>" target="_blank">Ver como candidato</a><a class="ui-btn ui-btn-ghost" href="<?= e(APP_URL); ?>/pages/candidaturas.php">Voltar à lista</a></div></div></aside></div>
<?php portal_layout_end(); ?>
